INSERT INTO cat.Brands
    (Id, Name, Description)
VALUES
    ('743c433e-f36b-1410-8adb-00ab2e36627d', 'LuminaTech', 'Specializing in circadian-aligned smart lighting and ocular-health focused hardware.'),
    ('773c433e-f36b-1410-8adb-00ab2e36627d', 'EcoVerve', 'Sustainable outdoor gear engineered from recycled ocean plastics and organic polymers.'),
    ('7a3c433e-f36b-1410-8adb-00ab2e36627d', 'AeroPace', 'High-performance ergonomic office solutions designed for long-duration cognitive tasks.'),
    ('7d3c433e-f36b-1410-8adb-00ab2e36627d', 'ZenithAudio', 'Audiophile-grade sound equipment focusing on spatial transparency and lossless wireless transmission.'),
    ('803c433e-f36b-1410-8adb-00ab2e36627d', 'VitaGlow', 'Bio-adaptive skincare utilizing peptide chains for dermatological restoration.'),
    ('833c433e-f36b-1410-8adb-00ab2e36627d', 'TerraTrek', 'Ruggedized exploration equipment for extreme thermal environments.'),
    ('863c433e-f36b-1410-8adb-00ab2e36627d', 'NovaKitchen', 'Precision culinary instruments with integrated IoT for molecular gastronomy.'),
    ('893c433e-f36b-1410-8adb-00ab2e36627d', 'PureFlow', 'Advanced water and air filtration systems using multi-stage HEPA and carbon nanotechnology.'),
    ('8c3c433e-f36b-1410-8adb-00ab2e36627d', 'OmniWear', 'Adaptive apparel featuring thermal-regulating fabric and biometric sensing threads.'),
    ('8f3c433e-f36b-1410-8adb-00ab2e36627d', 'TitanTools', 'Industrial-grade power tools with haptic feedback and brushless motor efficiency.');
