INSERT INTO cat.CatalogItems
    (Id, Slug, BaseName, IsPublished, CategoryId, BrandId, ShortSummary, SemanticDescription)
VALUES
    ('983c433e-f36b-1410-8adb-00ab2e36627d', 'quantum-sync-router', 'QuantumSync Mesh Router X1', 1, '903c433e-f36b-1410-8adb-00ab2e36627d', '743c433e-f36b-1410-8adb-00ab2e36627d', 'A high-performance networking hub designed to eliminate dead zones in multi-story residential buildings. It utilizes AI-driven beamforming technology to prioritize bandwidth for low-latency gaming and high-definition video conferencing simultaneously.', 'Tri-band Wi-Fi 7 wireless access point. PHY rates up to 19Gbps. Incorporates 6GHz spectrum, 320MHz channel width, and 4K-QAM modulation. Quad-core 2.2GHz ARM processor.'),
    ('9c3c433e-f36b-1410-8adb-00ab2e36627d', 'neural-link-headset', 'NeuralLink Cognitive Headset', 1, '923c433e-f36b-1410-8adb-00ab2e36627d', '743c433e-f36b-1410-8adb-00ab2e36627d', 'An advanced wearable device that monitors neural oscillations to provide real-time feedback on focus levels. Ideal for knowledge workers who need to optimize deep-work sessions and identify peak alertness windows.', 'Non-invasive EEG biosensor array. 16 dry-electrode channels for prefrontal cortex monitoring. Data via BLE 5.2. Integrated neurofeedback algorithms for Alpha/Beta wave modulation.'),
    ('a03c433e-f36b-1410-8adb-00ab2e36627d', 'ion-drive-fan', 'IonDrive Bladeless Purifier', 1, '903c433e-f36b-1410-8adb-00ab2e36627d', '743c433e-f36b-1410-8adb-00ab2e36627d', 'A silent, bladeless air circulation system that doubles as a medical-grade purifier. It uses ionic propulsion to move air, making it significantly quieter than traditional fans while capturing ultra-fine dust.', 'Bladeless air multiplier with H13 HEPA filtration. Airflow capacity 450 CFM. CADR rating 350m3/h. Features PM2.5 and VOC air quality sensors with real-time OLED telemetry.'),
