INSERT INTO cat.ProductReviews
    (Id, CatalogItemId, CustomerId, Rating, ReviewerAlias, ReviewText, CreatedAt)
VALUES
    ('ad46433e-f36b-1410-8adb-00ab2e36627d', 'a03d433e-f36b-1410-8adb-00ab2e36627d', '0fcc2f86-c2b8-4ec1-abe5-299790d94f75', 5, 'TechGuru88', 'The Wi-Fi 7 speeds are no joke. I finally have a stable connection in my basement office through three concrete walls. Setup via the app was seamless.', '2026-04-10 13:26:12.4966667'),
    ('b246433e-f36b-1410-8adb-00ab2e36627d', 'a03d433e-f36b-1410-8adb-00ab2e36627d', '152fd534-3fcf-468a-986b-3735a909bf79', 4, 'HomeUser_Jan', 'Great coverage, but the units are a bit larger than I expected. Signal is rock solid though.', '2026-04-10 13:26:12.4966667'),
    ('b746433e-f36b-1410-8adb-00ab2e36627d', '883d433e-f36b-1410-8adb-00ab2e36627d', '2814462e-3db7-42d2-9bfd-be335f817d0a', 5, 'PixelPerfect', 'The black levels on this OLED are incredible. Using it for color grading and the DCI-P3 accuracy is spot on right out of the box.', '2026-04-10 13:26:12.4966667'),
    ('bc46433e-f36b-1410-8adb-00ab2e36627d', '883d433e-f36b-1410-8adb-00ab2e36627d', '2d9e354b-c456-4457-9ddf-166152952dfd', 2, 'GamerX', 'Received with two dead pixels. For this price, quality control should be better. Returning for a replacement.', '2026-04-10 13:26:12.4966667'),
    ('c146433e-f36b-1410-8adb-00ab2e36627d', '083e433e-f36b-1410-8adb-00ab2e36627d', '30dfa509-23dd-4113-a2c7-b894e6df1730', 5, 'MountainMan', 'Took this on a 3-day trek. The weight distribution is perfect, barely felt the 30lb load on my shoulders.', '2026-04-10 13:26:12.4966667'),
    ('c646433e-f36b-1410-8adb-00ab2e36627d', 'fc3d433e-f36b-1410-8adb-00ab2e36627d', '32ac2e8a-5592-49ff-88fd-80936391aabb', 4, 'BioHacker_v2', 'The interstitial monitoring is highly accurate compared to my finger-prick device. The app UI needs a bit of work though.', '2026-04-10 13:26:12.4966667'),
    ('cb46433e-f36b-1410-8adb-00ab2e36627d', '683d433e-f36b-1410-8adb-00ab2e36627d', '34200a89-716b-4dfa-ab52-b23663d73bd2', 5, 'EcoTraveler', 'Wore this for three days straight while traveling—no odor at all. The merino blend is soft and definitely not itchy.', '2026-04-10 13:26:12.4966667'),
    ('d046433e-f36b-1410-8adb-00ab2e36627d', 'f43c433e-f36b-1410-8adb-00ab2e36627d', '3dd42643-ca4f-447b-8e68-8c66f56b1d6e', 3, 'StudyHard', 'I feel a slight increase in focus, but it might be a placebo. No jittery feeling though, which is good.', '2026-04-10 13:26:12.4966667'),
    ('d546433e-f36b-1410-8adb-00ab2e36627d', 'b83c433e-f36b-1410-8adb-00ab2e36627d', '59deea0b-a1eb-4191-a84f-c3265b186501', 5, 'ProContractor', 'This drill has more torque than my corded model. The haptic kickback protection saved my wrist yesterday on a masonry job.', '2026-04-10 13:26:12.4966667'),
    ('da46433e-f36b-1410-8adb-00ab2e36627d', '143e433e-f36b-1410-8adb-00ab2e36627d', '6b0211f7-f85c-4fd2-b952-f5945d6e1fe7', 5, 'ScentLover', 'The Sandalwood scent is deep and natural. It fills the room without being overwhelming. Buying the Lavender next.', '2026-04-10 13:26:12.4966667'),
    ('df46433e-f36b-1410-8adb-00ab2e36627d', 'c43d433e-f36b-1410-8adb-00ab2e36627d', '8fb738da-44a3-483a-a24e-dee77122fd5b', 4, 'VideoEditor', 'Fast transfer speeds for 4K raw footage. Fingerprint sensor is a nice security touch for travel.', '2026-04-10 13:26:12.4966667'),
    ('e446433e-f36b-1410-8adb-00ab2e36627d', 'cc3c433e-f36b-1410-8adb-00ab2e36627d', '9c1c2b6f-6852-45cc-a7d8-4c7c64b5ae4d', 5, 'DigitalNomad', 'Finally a single brick that charges my laptop and phone at full speed. Compact enough for my tech pouch.', '2026-04-10 13:26:12.4966667'),
    ('e946433e-f36b-1410-8adb-00ab2e36627d', 'e83d433e-f36b-1410-8adb-00ab2e36627d', 'a958c2d1-72d1-4eed-a921-a05b4adee1da', 5, 'CityCommuter', 'The carbon fiber frame makes this so much lighter than other e-bikes. Hills feel like flat ground now.', '2026-04-10 13:26:12.4966667'),
    ('ee46433e-f36b-1410-8adb-00ab2e36627d', '943d433e-f36b-1410-8adb-00ab2e36627d', 'c0e0258d-26c1-47de-98f4-60bb3fa4d812', 4, 'HealthNut', 'Water tastes much cleaner. The flow rate is a bit slow on the ultrafiltration mode, but that is expected.', '2026-04-10 13:26:12.4966667'),
    ('f346433e-f36b-1410-8adb-00ab2e36627d', 'b03c433e-f36b-1410-8adb-00ab2e36627d', 'c7a10fc9-1778-4b86-ae57-b970c78c6042', 5, 'CasualGamer', 'The haptic feedback is subtle but adds a whole new level of immersion. Battery life is fantastic.', '2026-04-10 13:26:12.4966667'),
    ('f846433e-f36b-1410-8adb-00ab2e36627d', 'f03d433e-f36b-1410-8adb-00ab2e36627d', 'e212b4d7-3e10-458b-8b4f-076ae39b606f', 5, 'AudiophileMike', 'Wide soundstage and very analytical. If you want to hear every breath in a recording, these are for you.', '2026-04-10 13:26:12.4966667'),
    ('fd46433e-f36b-1410-8adb-00ab2e36627d', 'cc3d433e-f36b-1410-8adb-00ab2e36627d', 'e50fe81d-ac13-4a6f-b137-cebc343fe575', 4, 'DevOps_Dan', 'The vapor chamber cooling actually works. Compiled a massive kernel and the fans barely ramped up.', '2026-04-10 13:26:12.4966667'),
    ('0247433e-f36b-1410-8adb-00ab2e36627d', 'b83d433e-f36b-1410-8adb-00ab2e36627d', 'e7e1c15e-11a8-41ac-a778-266f0596cbb8', 5, 'ChefInTraining', 'Perfect consistency for every batch. The IoT features are surprisingly helpful for long cooks.', '2026-04-10 13:26:12.4966667'),
    ('0747433e-f36b-1410-8adb-00ab2e36627d', 'c03d433e-f36b-1410-8adb-00ab2e36627d', 'f0f9814c-540d-43a1-b055-c4550dbd1325', 4, 'FragMaster', 'Surround sound is great for pinpointing footsteps. The mic is clear but a bit sensitive to background noise.', '2026-04-10 13:26:12.4966667'),
    ('0c47433e-f36b-1410-8adb-00ab2e36627d', 'dc3d433e-f36b-1410-8adb-00ab2e36627d', 'f6ea95c2-c1a5-4a66-b660-99243cc3ba13', 5, 'StudioHead', 'Render times cut in half. This workstation is an absolute beast for 8K video production.', '2026-04-10 13:26:12.4966667'),
    ('1147433e-f36b-1410-8adb-00ab2e36627d', 'd03d433e-f36b-1410-8adb-00ab2e36627d', 'f930ce5a-c4c9-4ce0-8070-ddce82b69123', 5, 'SoloHiker', 'Peace of mind in the backcountry. Sent a check-in message from a deep canyon with no issues.', '2026-04-10 13:26:12.4966667');
